import {characters,missions,practice} from './html5-dados.js';

const mode=document.body.dataset.mode;
const playerKey='portal-teste-html5-player-v1',simulationKey='portal-teste-html5-simulado-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true;
function read(key){try{return JSON.parse(localStorage.getItem(key))}catch{storageAvailable=false;return null}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{storageAvailable=false}showStorageWarning()}
function showStorageWarning(){if(!storageAvailable){$('storageWarning').hidden=false;$('storageWarning').textContent='O navegador não permitiu salvar o progresso. Você pode estudar normalmente nesta página, mas o progresso poderá ser perdido ao sair.'}}
const raw=read(playerKey)||{};
let player={character:characters.some(c=>c.id===raw.character)?raw.character:'ada',done:Array.isArray(raw.done)?[...new Set(raw.done.filter(id=>missions.some(m=>m.id===id)))]:[],labDone:Array.isArray(raw.labDone)?[...new Set(raw.labDone.filter(id=>missions.some(m=>m.id===id)))]:[],current:missions.some(m=>m.id===raw.current)?raw.current:missions[0].id,bestScore:Number.isInteger(raw.bestScore)&&raw.bestScore>=0&&raw.bestScore<=practice.length?raw.bestScore:0};
function character(){return characters.find(c=>c.id===player.character)}
function savePlayer(){const c=character();write(playerKey,{...player,avatar:c.icon,avatarName:c.name+' · '+c.role})}
function renderPlayer(){const c=character();$('playerPanel').innerHTML=`<div class="head-row"><div class="player"><span class="player-icon" aria-hidden="true">${c.icon}</span><div><strong>${esc(c.name)} · ${esc(c.role)}</strong><span class="small">${esc(c.description)}</span></div></div><button class="btn secondary" data-picker>Trocar personagem</button></div><div class="rewards" style="margin-top:15px"><span class="pill">⭐ ${player.done.length*100+player.labDone.length*50} XP na trilha</span><span class="pill">🏅 ${player.done.length} de 8 checkpoints</span><span class="pill">🧪 ${player.labDone.length} de 8 laboratórios validados</span><span class="pill">🏆 Melhor simulado: ${player.bestScore} / 40</span></div>`;renderCharacters()}
function renderCharacters(){$('characters').innerHTML=characters.map(c=>`<button class="character ${c.id===player.character?'selected':''}" data-character="${c.id}" aria-pressed="${c.id===player.character}"><span class="portrait" aria-hidden="true">${c.icon}</span><strong>${esc(c.name)}</strong><span class="role">${esc(c.role)}</span><p>${esc(c.description)}</p></button>`).join('')}

let gateAnswer=null;const labKey='portal-teste-html5-labs-v1',savedLabs=read(labKey),labDrafts=savedLabs&&typeof savedLabs==='object'&&!Array.isArray(savedLabs)?savedLabs:{};
function renderTrail(){renderPlayer();$('trailProgress').innerHTML=`<div class="progress" role="progressbar" aria-label="Missões concluídas" aria-valuemin="0" aria-valuemax="8" aria-valuenow="${player.done.length}"><i style="width:${player.done.length/8*100}%"></i></div><span class="small">${player.done.length} de 8 checkpoints concluídos</span>`;$('labProgress').innerHTML=`<div class="progress" role="progressbar" aria-label="Laboratórios validados" aria-valuemin="0" aria-valuemax="8" aria-valuenow="${player.labDone.length}"><i style="width:${player.labDone.length/8*100}%"></i></div><span class="small">${player.labDone.length} de 8 laboratórios validados</span>`;$('missionMap').innerHTML=missions.map((m,i)=>`<button class="mission-node ${player.current===m.id?'current':''} ${player.done.includes(m.id)?'done':''}" data-mission="${m.id}" ${player.current===m.id?'aria-current="step"':''}><span class="symbol" aria-hidden="true">${m.icon}</span><span><small>Missão ${i+1}${player.done.includes(m.id)?' · checkpoint ✓':''}${player.labDone.includes(m.id)?' · laboratório ✓':''}</small><strong>${esc(m.title)}</strong></span></button>`).join('');renderLesson();$('trailFinish').hidden=player.done.length!==missions.length||player.labDone.length!==missions.length;if(player.done.length===missions.length&&player.labDone.length===missions.length)$('trailFinish').innerHTML="<h2>🏆 Trilha concluída: hora do projeto final</h2><p>Você estudou 60 conceitos e experimentou oito laboratórios. Crie uma página de apresentação de uma disciplina ou projeto da sua turma.</p><div class=\"final-project\"><h3>Checklist do projeto</h3><ol><li>Comece com doctype, html lang, head, title, charset e viewport.</li><li>Organize header, nav, main, section e footer com títulos em ordem.</li><li>Inclua parágrafos, uma lista e links com textos descritivos.</li><li>Adicione uma imagem com alt e legenda em figure.</li><li>Monte uma tabela de dados com caption e cabeçalhos.</li><li>Crie um formulário com label, name e validação inicial.</li><li>Use details para uma dica e confira a página no celular e com teclado.</li></ol><p>Teste os links, as imagens e os campos antes de compartilhar.</p></div><div class=\"actions\"><a class=\"btn\" href=\"html5-simulado.html\">Praticar os 40 desafios →</a><a class=\"btn secondary\" href=\"html5.html\">Ver a prova em preparação</a></div>"}
function renderTagAtlas(m){return `<section class="tag-atlas" aria-label="Tags e atributos desta missão"><div class="chapter-label">Kit de tags e atributos</div><div class="tag-list">${m.tags.map(t=>`<code>${esc(t)}</code>`).join('')}</div><p class="small">Use este kit como referência; entenda a função de cada tag antes de memorizá-la.</p></section>`}
function renderConcept(c){const [title,definition,example,code]=c;return `<article class="concept"><h3>${esc(title)}</h3><p>${esc(definition)}</p><div class="example"><strong>EXEMPLO PRÁTICO</strong>${esc(example)}</div><code class="inline-code">${esc(code)}</code></article>`}
function evaluateLab(id,code){
 const doc=new DOMParser().parseFromString(code,'text/html'),q=s=>doc.querySelector(s),all=s=>[...doc.querySelectorAll(s)],txt=s=>q(s)?.textContent.trim()||'',result=[];
 const add=(label,ok,hint)=>result.push({label,ok:!!ok,hint});
 const labeled=el=>!!el?.id&&all('label[for]').some(label=>label.htmlFor===el.id);
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(id==='estrutura'){
  add('Declaração <!doctype html> na primeira linha',/^\s*<!doctype\s+html\s*>/i.test(code),'Comece o arquivo com <!doctype html>.');
  add('Idioma pt-BR no elemento <html>',doc.documentElement.getAttribute('lang')?.toLowerCase()==='pt-br','Abra o documento com <html lang="pt-BR">.');
  add('<head> com UTF-8 e viewport',/<head\b/i.test(code)&&!!q('head meta[charset="utf-8"]')&&!!q('head meta[name="viewport"][content*="width=device-width"]'),'Inclua <meta charset="utf-8"> e a meta viewport dentro de head.');
  add('Título da aba personalizado',!!doc.title.trim()&&doc.title.trim()!=='Minha primeira página','Troque o texto de <title> pelo nome do seu projeto.');
  add('Título visível personalizado em <body>',/<body\b/i.test(code)&&!!txt('body h1')&&txt('body h1')!=='Olá, mundo!','Troque o texto do h1 e mantenha-o dentro de body.');
 }
 if(id==='texto'){
  add('Título principal com novo tema',!!txt('h1')&&txt('h1')!=='Curso de HTML5','Troque o tema do h1 para seu próprio curso.');
  add('Dois parágrafos ou mais',all('p').length>=2,'Acrescente um novo <p> para explicar o curso.');
  add('Três materiais em <ul>',all('ul li').length>=3,'Acrescente pelo menos três <li> à lista de materiais.');
  add('Três etapas em <ol>',all('ol li').length>=3,'Acrescente pelo menos três <li> à lista ordenada.');
  add('Seções com títulos <h2>',all('h2').length>=2,'Mantenha títulos h2 para Materiais e Etapas.');
 }
 if(id==='links'){
  add('Menu em <nav>',!!q('nav'),'Agrupe os links principais dentro de <nav>.');
  add('Link para #materiais no menu',!!q('nav a[href="#materiais"]')&&norm(txt('nav a[href="#materiais"]')).includes('materiais'),'Crie no menu um link descritivo com href="#materiais".');
  add('Seção materiais com título',!!q('section#materiais h2'),'Crie <section id="materiais"> com um h2.');
  const ids=all('[id]').map(el=>el.id);add('Identificadores sem repetição',ids.length===new Set(ids).size,'Cada id deve ser único na página.');
 }
 if(id==='midia'){
  const img=q('figure img'),caption=txt('figure figcaption');
  add('Imagem própria dentro de <figure>',!!img?.getAttribute('src')&&img.getAttribute('src')!=='foto.jpg','Troque foto.jpg pelo caminho de uma imagem sua dentro de figure.');
  const alt=img?.getAttribute('alt')?.trim()||'';add('Texto alternativo informativo',alt.length>=12&&!/^(imagem|foto|figura)( de)?$/i.test(alt),'Descreva em alt a informação principal da foto, com pelo menos 12 caracteres.');
  add('Legenda com contexto próprio',!!caption&&caption!=='Equipe em atividade no laboratório.','Escreva uma legenda que acrescente contexto à imagem.');
  add('Dimensões da imagem',!!img?.getAttribute('width')&&!!img?.getAttribute('height'),'Informe width e height para reservar espaço na página.');
 }
 if(id==='semantica'){
  add('Regiões principais',!!q('header')&&!!q('nav')&&!!q('main')&&!!q('footer'),'Mantenha header, nav, main e footer com seus papéis.');
  add('Duas notícias independentes',all('main article').length>=2,'Acrescente uma segunda notícia em outro <article>.');
  add('Agenda como seção com título',!!q('main section#agenda h2'),'Crie <section id="agenda"> com um h2 dentro de main.');
  add('Texto em cada notícia',all('main article').slice(0,2).every(article=>!!article.querySelector('h2')&&!!article.querySelector('p')),'Cada article precisa de título h2 e parágrafo.');
 }
 if(id==='tabelas'){
  const headers=all('table thead th'),rows=all('table tbody tr');
  add('Tabela com legenda',!!txt('table caption'),'Inclua <caption> para nomear os dados.');
  add('Coluna Situação no cabeçalho',headers.length>=3&&headers.some(th=>norm(th.textContent).includes('situacao')&&th.getAttribute('scope')==='col'),'Acrescente <th scope="col">Situação</th> no cabeçalho.');
  add('Pelo menos três alunos',rows.length>=3,'Acrescente uma terceira linha <tr> dentro de tbody.');
  add('Três células em cada linha',rows.length>=3&&rows.every(row=>row.querySelectorAll(':scope > th, :scope > td').length>=3),'Cada linha do corpo deve conter aluno, nota e situação.');
  add('Nome como cabeçalho de linha',rows.length>=3&&rows.every(row=>row.querySelector('th[scope="row"]')),'Marque o nome de cada aluno com <th scope="row">.');
 }
 if(id==='formularios'){
  const form=q('form'),message=q('form textarea'),select=q('form select');
  add('Formulário e botão de envio',!!form&&!!q('form button[type="submit"]'),'Mantenha form e button type="submit".');
  add('Mensagem com rótulo e name',!!message?.getAttribute('name')&&labeled(message),'Crie textarea com id, name e um label for correspondente.');
  add('Turma com rótulo e name',!!select?.getAttribute('name')&&labeled(select),'Crie select com id, name e um label for correspondente.');
  add('Duas turmas disponíveis',!!select&&select.querySelectorAll('option[value]').length>=2,'Inclua pelo menos duas opções com value no select.');
  add('Campos essenciais com validação',!!q('form input[name="nome"][required]')&&!!q('form input[name="email"][type="email"][required]'),'Mantenha nome e e-mail obrigatórios com tipo apropriado.');
 }
 if(id==='avancado'){
  const progress=q('progress'),details=all('details');
  add('Progresso atualizado para 7 de 8',progress?.getAttribute('value')==='7'&&progress?.getAttribute('max')==='8','Altere progress para value="7" e mantenha max="8".');
  add('Duas dicas expansíveis',details.length>=2,'Acrescente um segundo bloco <details>.');
  add('Segunda dica com título e explicação',!!details[1]?.querySelector('summary')?.textContent.trim()&&!!details[1]?.querySelector('p')?.textContent.trim(),'Inclua summary e um parágrafo na nova dica.');
  add('Data marcada com <time>',!!q('time[datetime]'),'Mantenha time com o atributo datetime.');
 }
 return result
}
function updateLabFeedback(award){
 if(mode!=='trail')return;const m=missions.find(item=>item.id===player.current),editor=$('labEditor'),box=$('labFeedback');if(!m||!editor||!box)return;
 const checks=evaluateLab(m.id,editor.value),passed=checks.filter(c=>c.ok).length,complete=checks.length>0&&passed===checks.length;
 box.innerHTML=`<div class="lab-score ${complete?'complete':''}"><strong>${complete?'✓ Exercício aprovado!':`${passed} de ${checks.length} requisitos atendidos`}</strong><span>${complete?'Você cumpriu os critérios desta missão.':'Edite o código para atender aos itens abaixo.'}</span></div><ul class="lab-checks">${checks.map(c=>`<li class="${c.ok?'pass':'pending'}"><strong>${c.ok?'✓':'○'} ${esc(c.label)}</strong>${c.ok?'':`<span>${esc(c.hint)}</span>`}</li>`).join('')}</ul><p class="small">Esta verificação analisa elementos e atributos. Confira também se a página faz sentido e funciona ao navegar por teclado.</p>`;
 if(complete&&award&&!player.labDone.includes(m.id)){player.labDone.push(m.id);savePlayer();renderPlayer();$('labStatus').textContent='Laboratório validado! +50 XP.';const labBar=$('labProgress');if(labBar)labBar.innerHTML=`<div class="progress" role="progressbar" aria-label="Laboratórios validados" aria-valuemin="0" aria-valuemax="${missions.length}" aria-valuenow="${player.labDone.length}"><i style="width:${player.labDone.length/missions.length*100}%"></i></div><span class="small">${player.labDone.length} de ${missions.length} laboratórios validados</span>`;$('trailFinish').hidden=player.done.length!==missions.length||player.labDone.length!==missions.length}
}
function renderLab(m){const lab=m.lab,code=typeof labDrafts[m.id]==='string'?labDrafts[m.id]:lab.sample;return `<section class="lab"><div class="chapter-label">Aprender fazendo</div><h3>${esc(lab.title)}</h3><p class="muted">${esc(lab.observe)}</p><div class="lab-flow" aria-label="Etapas do exercício"><span>1 · Leia o desafio</span><span>2 · Escreva sua resposta</span><span>3 · Verifique</span></div><div class="lab-task" id="labTask"><span class="lab-step">Etapa 1 de 3</span><h4>O que você precisa fazer</h4><p>${esc(lab.task)}</p><ol>${lab.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><button class="btn" type="button" data-focus-lab>Ir para minha resposta ↓</button></div><div class="lab-grid"><div class="lab-answer"><span class="lab-step">Etapa 2 de 3</span><label for="labEditor"><strong>Sua resposta: edite o código HTML</strong></label><p class="small">Escreva no campo escuro abaixo. O exemplo inicial já está pronto para você modificar.</p><textarea id="labEditor" spellcheck="false" aria-describedby="labHelp">${esc(code)}</textarea><p class="small" id="labHelp">Seu rascunho fica salvo neste navegador. A prévia não executa scripts.</p><div class="actions"><button class="btn" data-check-lab>3 · Verificar minha resposta</button><button class="btn secondary" data-run-lab>Atualizar prévia</button><button class="btn secondary" data-copy-code>Copiar código</button><button class="btn secondary" data-reset-lab>Restaurar exemplo</button></div><p class="small" id="labStatus" role="status"></p><div id="labFeedback" class="lab-feedback" aria-live="polite"></div></div><div class="lab-result"><strong>Prévia: como sua página aparece</strong><iframe id="labPreview" class="lab-preview" title="Prévia do exercício HTML" sandbox srcdoc="${esc(code)}"></iframe><p class="small">A prévia mostra sua página. Use “Verificar minha resposta” para saber se cumpriu o desafio.</p></div></div><details class="lab-solution"><summary>Preciso de ajuda: ver uma solução possível</summary><pre><code>${esc(lab.solution)}</code></pre></details></section>`}function handleLabClick(t){const m=missions.find(item=>item.id===player.current),editor=$('labEditor'),preview=$('labPreview'),status=$('labStatus');if(!m||!editor||!preview)return;if(t.hasAttribute('data-focus-lab')){editor.focus();editor.scrollIntoView({block:'center',behavior:'smooth'});return}if(t.hasAttribute('data-run-lab')){preview.srcdoc=editor.value;status.textContent='Prévia atualizada.';return}if(t.hasAttribute('data-reset-lab')){editor.value=m.lab.sample;preview.srcdoc=editor.value;labDrafts[m.id]=editor.value;write(labKey,labDrafts);status.textContent='Exemplo restaurado.';return}if(t.hasAttribute('data-copy-code')){if(typeof navigator!=='undefined'&&navigator.clipboard?.writeText)navigator.clipboard.writeText(editor.value).then(()=>{status.textContent='Código copiado.'}).catch(()=>{status.textContent='Selecione e copie o código manualmente.'});else status.textContent='Selecione e copie o código manualmente.'}}
function renderLesson(){const m=missions.find(m=>m.id===player.current),i=missions.indexOf(m),done=player.done.includes(m.id),gate=m.gate,answered=gateAnswer!==null,correct=gateAnswer===gate.c;$('lesson').innerHTML=`<div class="chapter-label">${esc(m.world)} · missão ${i+1} de 8</div><h2 style="margin-top:9px">${m.icon} ${esc(m.title)}</h2><p class="muted">${esc(m.intro)}</p><div class="mission-goal"><strong>Objetivo da missão</strong><p>${esc(m.goal)}</p></div>${renderTagAtlas(m)}<div class="concepts">${m.concepts.map(renderConcept).join('')}</div>${renderLab(m)}<div class="checkpoint"><div class="chapter-label">Checkpoint da missão</div><h3 style="margin-top:10px">${esc(gate.q)}</h3>${gate.o.map((o,j)=>`<button class="option ${answered&&j===gate.c?'correct':''} ${answered&&j===gateAnswer&&!correct?'wrong':''}" data-gate="${j}" ${answered?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}${answered?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'✓ Missão concluída!':'Vamos revisar a decisão.'}</strong><br>${esc(gate.why)}</div>${!correct?'<div class="actions"><button class="btn secondary" data-retry-gate>Tentar novamente</button></div>':''}`:''}${done&&!answered?'<p class="small">✓ Esta missão já está concluída. Você pode rever o desafio quando quiser.</p>':''}</div><div class="actions">${i>0?`<button class="btn secondary" data-mission="${missions[i-1].id}">← Missão anterior</button>`:''}${i<missions.length-1?`<button class="btn" data-mission="${missions[i+1].id}">Próxima missão →</button>`:'<a class="btn" href="html5-simulado.html">Praticar no simulado →</a>'}<a class="btn secondary" href="./">Sair da trilha</a></div><div class="sources">Referências: <a href="https://html.spec.whatwg.org/multipage/" target="_blank" rel="noopener">Padrão HTML</a><a href="https://developer.mozilla.org/pt-BR/docs/Web/HTML" target="_blank" rel="noopener">Guia HTML da MDN</a></div>`;updateLabFeedback(true)}

export function validCampaign(s){return !!s&&Array.isArray(s.order)&&s.order.length===practice.length&&new Set(s.order).size===practice.length&&s.order.every(i=>Number.isInteger(i)&&i>=0&&i<practice.length)&&Array.isArray(s.answers)&&s.answers.length===practice.length&&s.answers.every(a=>a===null||Number.isInteger(a)&&a>=0&&a<4)&&Number.isInteger(s.cursor)&&s.cursor>=0&&s.cursor<practice.length&&typeof s.finished==='boolean'}
let campaign=null,running=false;
if(mode==='simulation'){const saved=read(simulationKey);if(validCampaign(saved))campaign=saved}
function saveCampaign(){if(campaign)write(simulationKey,campaign)}
function newCampaign(){const order=practice.map((_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}campaign={order,answers:Array(practice.length).fill(null),cursor:0,finished:false};saveCampaign()}
function simulationScore(){return campaign.answers.reduce((n,a,i)=>n+(a===practice[campaign.order[i]].correct?1:0),0)}
function renderSimulation(){renderPlayer();$('simulationIntro').hidden=running;$('simulationMap').hidden=!running;$('quiz').hidden=!running||campaign?.finished;$('simulationResult').hidden=!running||!campaign?.finished;if(!running){$('beginSimulation').textContent=campaign?.finished?'Ver meu resultado':campaign?'Retomar campanha →':'Começar campanha →';return}const answered=campaign.answers.filter(a=>a!==null).length;$('simulationCount').textContent=`${answered} de 40 respondidos`;$('simulationBar').style.width=answered/practice.length*100+'%';$('questionMap').innerHTML=campaign.order.map((_,i)=>`<button class="question-node ${i===campaign.cursor?'current':''} ${campaign.answers[i]!==null?'done':''}" data-question="${i}" aria-label="Desafio ${i+1}${campaign.answers[i]!==null?', respondido':''}">${i+1}</button>`).join('');if(campaign.finished){renderResult();return}const q=practice[campaign.order[campaign.cursor]],m=missions.find(m=>m.id===q.mission),choice=campaign.answers[campaign.cursor],hasAnswer=choice!==null,correct=choice===q.correct;$('quiz').innerHTML=`<div class="head-row"><span class="chapter-label">Desafio ${campaign.cursor+1} de 40</span><span class="pill">${m.icon} ${esc(m.world)}</span></div><p class="small" style="margin-top:9px">${esc(m.title)}</p><h2 class="quiz-title">${esc(q.text)}</h2>${q.options.map((o,i)=>`<button class="option ${hasAnswer&&i===q.correct?'correct':''} ${hasAnswer&&i===choice&&!correct?'wrong':''}" data-answer="${i}" ${hasAnswer?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${hasAnswer?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'✓ Boa decisão! +20 XP':'Vamos fortalecer este conceito.'}</strong><br>${esc(q.explain)}</div>`:''}<div class="actions">${hasAnswer?`<button class="btn" data-next>${campaign.cursor===practice.length-1?'Concluir campanha →':'Próximo desafio →'}</button>`:''}<a class="btn secondary" href="html5-trilha.html?missao=${m.id}">Revisar este assunto</a><a class="btn secondary" href="./">Sair do simulado</a></div><p class="small" style="margin-top:15px">${storageAvailable?'Progresso salvo neste navegador. Você pode sair e retomar a campanha.':'O progresso não está sendo salvo neste navegador.'}</p>`}
function renderResult(){const score=simulationScore(),rank=score>=36?'S':score>=32?'A':score>=28?'B':score>=24?'C':'D';$('simulationResult').innerHTML=`<div class="head-row"><div><div class="chapter-label">Campanha concluída</div><h2 style="margin-top:8px">Sua equipe ganhou experiência</h2></div><span class="rank">RANK ${rank}</span></div><div class="score">${score} / 40</div><p class="muted">${score>=32?'Você demonstrou boa compreensão dos conceitos. Continue revisando para explicar suas decisões com segurança.':'Use as explicações e as missões abaixo para revisar os conceitos e tentar novamente.'}</p><div class="rewards"><span class="pill">⭐ ${score*20} XP no treino</span><span class="pill">💎 ${score*5} pontos de experiência</span></div><h3 style="margin-top:23px">Revisão por missão</h3><div class="review-grid">${missions.map(m=>{const entries=campaign.order.map((q,i)=>({q:practice[q],a:campaign.answers[i]})).filter(e=>e.q.mission===m.id),hits=entries.filter(e=>e.a===e.q.correct).length;return `<a class="review-link" href="html5-trilha.html?missao=${m.id}"><strong>${m.icon} ${esc(m.title)}</strong><br><span>${hits} de ${entries.length} acertos · revisar missão</span></a>`}).join('')}</div><div class="actions"><button class="btn secondary" data-restart>Jogar novamente</button><a class="btn" href="html5.html">Ir para a prova com código →</a><a class="btn secondary" href="./">Voltar ao portal</a></div><p class="small" style="margin-top:15px">A pontuação é apenas de estudo. A nota oficial é calculada na prova e registrada no painel do professor.</p>`}

document.addEventListener('click',event=>{const t=event.target.closest('button');if(!t)return;
  if(mode==='trail'&&(t.hasAttribute('data-focus-lab')||t.hasAttribute('data-run-lab')||t.hasAttribute('data-reset-lab')||t.hasAttribute('data-copy-code')||t.hasAttribute('data-check-lab'))){handleLabClick(t);if(t.hasAttribute('data-check-lab')||t.hasAttribute('data-reset-lab'))updateLabFeedback(true);return}
  if(t.hasAttribute('data-picker')){$('characterPicker').hidden=!$('characterPicker').hidden;return}
  if(t.dataset.character){if(!characters.some(c=>c.id===t.dataset.character))return;player.character=t.dataset.character;savePlayer();renderPlayer();$('characterPicker').hidden=true;return}
  if(mode==='trail'){
    if(t.dataset.mission){if(!missions.some(m=>m.id===t.dataset.mission))return;player.current=t.dataset.mission;gateAnswer=null;savePlayer();renderTrail();$('lesson').scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-gate')){if(gateAnswer!==null)return;const m=missions.find(m=>m.id===player.current),value=Number(t.dataset.gate);if(!Number.isInteger(value)||value<0||value>=m.gate.o.length)return;gateAnswer=value;if(value===m.gate.c&&!player.done.includes(m.id)){player.done.push(m.id);savePlayer()}renderTrail();return}
    if(t.hasAttribute('data-retry-gate')){gateAnswer=null;renderLesson();return}
  }
  if(mode==='simulation'){
    if(t.hasAttribute('data-start')){if(!campaign)newCampaign();running=true;renderSimulation();(campaign.finished?$('simulationResult'):$('quiz')).scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-answer')){if(!campaign||campaign.answers[campaign.cursor]!==null)return;const choice=Number(t.dataset.answer);if(!Number.isInteger(choice)||choice<0||choice>3)return;campaign.answers[campaign.cursor]=choice;saveCampaign();renderSimulation();return}
    if(t.hasAttribute('data-next')){if(!campaign||campaign.answers[campaign.cursor]===null)return;if(campaign.cursor===practice.length-1){const missed=campaign.answers.indexOf(null);if(missed===-1){campaign.finished=true;player.bestScore=Math.max(player.bestScore,simulationScore());savePlayer()}else campaign.cursor=missed}else campaign.cursor++;saveCampaign();renderSimulation();(campaign.finished?$('simulationResult'):$('quiz')).scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-question')){const i=Number(t.dataset.question);if(!campaign||!Number.isInteger(i)||i<0||i>=practice.length)return;campaign.cursor=i;campaign.finished=false;saveCampaign();renderSimulation();$('quiz').scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-restart')&&confirm('Começar uma nova campanha? O resultado anterior continua como recorde, mas as respostas desta campanha serão reiniciadas.')){newCampaign();running=true;renderSimulation();$('quiz').scrollIntoView({block:'start'});return}
  }
});
let labTimer=null;document.addEventListener('input',event=>{if(mode!=='trail'||event.target?.id!=='labEditor')return;labDrafts[player.current]=event.target.value;write(labKey,labDrafts);clearTimeout(labTimer);labTimer=setTimeout(()=>updateLabFeedback(true),350)});
if(mode==='trail'){const requested=new URLSearchParams(location.search).get('missao');if(missions.some(m=>m.id===requested))player.current=requested;renderTrail()}else renderSimulation();
if(!raw.character)$('characterPicker').hidden=false;
showStorageWarning();
